class Solution {
public:
    int maximumElementAfterDecrementingAndRearranging(vector<int>& arr) {
        int n = arr.size();
        vector<int> count(n + 1, 0);
        for (int x : arr) {
            count[min(x, n)]++;
        }
        int cur = 0;
        for (int v = 1; v <= n; v++) {
            cur = min(v, cur + count[v]);
        }
        return cur;
    }
};
